// Set Scale, the Python number formatters of Core/Domain/NumberText.* (plan 4.6, 5.4, tests-first): format_g (f"{v:g}"), format_general (format(v, ".<p>g")),
// format_fixed (f"{v:.<d>f}") and format_fixed_trimmed (round + .<d>f + rstrip("0").rstrip(".")).
// Oracle: PageScaleNumberOracleData.hpp, GENERATED by executing CPython 3.11.4 read-only (python -B -I) on the exact doubles of the table (hex literals); the Windows
// expressions are set_scale_dialog.py:348-350, scales.py:58-74, overlay_rect.py:44-48, serialization.py:18-28 and legend_position.py:25.
// These must hold on MSVC AND on AppleClang (plan 4.6): the C library is allowed to differ from Python in the spelling of inf / nan, in the exponent digits and in
// the rounding of an exact tie, and in how many digits %f prints for a huge value; the formatters hide those differences.
#include "FormattingTestSupport.hpp"

#include "Domain/NumberText.hpp"

#include "PageScaleNumberOracleData.hpp"

#include <cmath>
#include <string>

using namespace ost_domain;
using std::string;

namespace
{
    string value_name(double value)
    {
        return ost_test::detail::exact_float(value);
    }
}

// ---- every oracle row ---------------------------------------------------------------------------------------------------------------------

// Python f"{v:g}" on every row of kFormatG (six significant digits, exponent form below 1e-4 and from 1e6, "inf" / "-inf" / "nan", "-0").
TEST(SetScale_NumberText, FormatGMatchesPythonOnEveryRow)
{
    int rows = 0;
    for (const scale_oracle::FormatRow &row : scale_oracle::kFormatG)
    {
        SCOPED_CONTEXT("value " + value_name(row.value));
        CHECK_STR_EQ(format_g(row.value), row.expected);
        ++rows;
    }
    CHECK(rows >= 60);
}

// Python format(v, ".<p>g") on every row of kFormatGeneral (precisions 1, 3, 6, 15, 17 on 23 values and precision 15 on the whole value table).
TEST(SetScale_NumberText, FormatGeneralMatchesPythonOnEveryRow)
{
    int rows = 0;
    for (const scale_oracle::PrecisionRow &row : scale_oracle::kFormatGeneral)
    {
        SCOPED_CONTEXT("value " + value_name(row.value) + " precision " + std::to_string(row.precision));
        CHECK_STR_EQ(format_general(row.value, row.precision), row.expected);
        ++rows;
    }
    CHECK(rows >= 150);
}

// Python f"{v:.<d>f}" on every row of kFormatFixed (6, 3 and 0 decimals; the exact expansion of 1e22, 1e23, 2**-1074 and 1.797e308; "-0.000000"; inf / nan).
TEST(SetScale_NumberText, FormatFixedMatchesPythonOnEveryRow)
{
    int rows = 0;
    for (const scale_oracle::PrecisionRow &row : scale_oracle::kFormatFixed)
    {
        SCOPED_CONTEXT("value " + value_name(row.value) + " decimals " + std::to_string(row.precision));
        CHECK_STR_EQ(format_fixed(row.value, row.precision), row.expected);
        ++rows;
    }
    CHECK(rows >= 60);
}

// Python f"{round(v, d):.<d>f}".rstrip("0").rstrip(".") on every row of kFormatFixedTrimmed (3, 2, 6 and 0 decimals; exact ties; negative zero; huge values).
TEST(SetScale_NumberText, FormatFixedTrimmedMatchesPythonOnEveryRow)
{
    int rows = 0;
    for (const scale_oracle::PrecisionRow &row : scale_oracle::kFormatFixedTrimmed)
    {
        SCOPED_CONTEXT("value " + value_name(row.value) + " decimals " + std::to_string(row.precision));
        CHECK_STR_EQ(format_fixed_trimmed(row.value, row.precision), row.expected);
        ++rows;
    }
    CHECK(rows >= 120);
}

// ---- readable examples of the contract (each also in the tables) ---------------------------------------------------------------------------

// set_scale_dialog.py:348-350: f"{value:g}" keeps six digits. This is WHY the iOS form does not use it (register SS-5): 12.0000001 reads back as 12.
TEST(SetScale_NumberText, FormatGKeepsSixSignificantDigits)
{
    CHECK_STR_EQ(format_g(100000.0), "100000");
    CHECK_STR_EQ(format_g(1e6), "1e+06");
    CHECK_STR_EQ(format_g(0.0001), "0.0001");
    CHECK_STR_EQ(format_g(1e-5), "1e-05");
    CHECK_STR_EQ(format_g(12.0000001), "12");
    CHECK_STR_EQ(format_g(0.125), "0.125");
    CHECK_STR_EQ(format_g(192.0), "192"); // the Windows test_set_scale_apply.py:181 custom field text
    CHECK_STR_EQ(format_g(-0.0), "-0");
}

// scales.py:58-74: ".15g" trims float noise to fifteen digits and keeps the exponent form of tiny values.
TEST(SetScale_NumberText, FormatGeneralFifteenDigitsTrimsFloatNoise)
{
    CHECK_STR_EQ(format_general(0.1 + 0.2, 15), "0.3");
    CHECK_STR_EQ(format_general(1.0, 15), "1");
    CHECK_STR_EQ(format_general(1234567.5, 15), "1234567.5");
    CHECK_STR_EQ(format_general(0.000000123456789, 15), "1.23456789e-07");
    CHECK_STR_EQ(format_general(0.123456789012345678, 15), "0.123456789012346");
    CHECK_STR_EQ(format_general(1234567.12345678912, 15), "1234567.12345679");
    CHECK_STR_EQ(format_general(12.0000001, 15), "12.0000001");
}

// A precision below 1 is read as 1, like Python (format(x, ".0g") is "%.1g").
TEST(SetScale_NumberText, FormatGeneralReadsPrecisionBelowOneAsOne)
{
    CHECK_STR_EQ(format_general(1234.5, 0), "1e+03");
    CHECK_STR_EQ(format_general(1234.5, -3), "1e+03");
    CHECK_STR_EQ(format_general(1234.5, 1), "1e+03");
    CHECK_STR_EQ(format_general(5.0, 0), "5");
}

// overlay_rect.py:44-48: six decimals of the EXACT binary value, however large.
TEST(SetScale_NumberText, FormatFixedIsExactForLargeAndTinyValues)
{
    CHECK_STR_EQ(format_fixed(4029.2421345, 6), "4029.242134"); // the double below the tie: Python prints ...134
    CHECK_STR_EQ(format_fixed(1e22, 6), "10000000000000000000000.000000");
    CHECK_STR_EQ(format_fixed(1e23, 6), "99999999999999991611392.000000");
    CHECK_STR_EQ(format_fixed(-1e-7, 6), "-0.000000");
    CHECK_STR_EQ(format_fixed(-0.0, 6), "-0.000000");
    CHECK_STR_EQ(format_fixed(0.5, 0), "0");       // an exact tie goes to the even digit
    CHECK_STR_EQ(format_fixed(1.5, 0), "2");
    CHECK_STR_EQ(format_fixed(2.5, 0), "2");
}

// serialization.py:18-28: trailing zeros and a trailing dot are trimmed, an exact tie goes to the even digit, the sign of a negative zero is kept.
TEST(SetScale_NumberText, FormatFixedTrimmedTrimsAndRoundsLikeWindows)
{
    CHECK_STR_EQ(format_fixed_trimmed(0.5, 3), "0.5");
    CHECK_STR_EQ(format_fixed_trimmed(2.0, 3), "2");
    CHECK_STR_EQ(format_fixed_trimmed(370.3701, 3), "370.37");
    CHECK_STR_EQ(format_fixed_trimmed(0.0004, 3), "0");
    CHECK_STR_EQ(format_fixed_trimmed(-0.0004, 3), "-0");
    CHECK_STR_EQ(format_fixed_trimmed(0.0625, 3), "0.062");
    CHECK_STR_EQ(format_fixed_trimmed(0.1875, 3), "0.188");
    CHECK_STR_EQ(format_fixed_trimmed(100.0, 3), "100"); // zeros before the point are NOT trimmed: only the fraction's
    CHECK_STR_EQ(format_fixed_trimmed(1e22, 3), "10000000000000000000000");
}

// ---- the non-finite spellings and the locale ------------------------------------------------------------------------------------------------

// Python never writes "1.#INF", "-nan(ind)" or "nan(ind)"; a NaN of either sign is "nan", the infinities "inf" / "-inf" (the oracle rows, spelled out).
TEST(SetScale_NumberText, NonFiniteValuesAreSpelledLikePython)
{
    const double inf = std::numeric_limits<double>::infinity();
    const double nan = std::numeric_limits<double>::quiet_NaN();
    const double negative_nan = -std::numeric_limits<double>::quiet_NaN();
    for (const double value : {nan, negative_nan})
    {
        CHECK_STR_EQ(format_g(value), "nan");
        CHECK_STR_EQ(format_general(value, 15), "nan");
        CHECK_STR_EQ(format_fixed(value, 6), "nan");
        CHECK_STR_EQ(format_fixed_trimmed(value, 3), "nan");
    }
    CHECK_STR_EQ(format_g(inf), "inf");
    CHECK_STR_EQ(format_g(-inf), "-inf");
    CHECK_STR_EQ(format_general(-inf, 15), "-inf");
    CHECK_STR_EQ(format_fixed(inf, 6), "inf");
    CHECK_STR_EQ(format_fixed_trimmed(-inf, 3), "-inf");
}

// "No locale-dependent formatting anywhere" (plan 4.6): in a decimal-comma locale every formatter still writes '.'. Skipped when the machine has no such locale.
TEST(SetScale_NumberText, NoFormatterWritesALocaleDecimalComma)
{
    fmt_test::ScopedDecimalCommaLocale locale;
    if (!locale.active())
        return; // no decimal-comma locale installed here: nothing to prove
    CHECK_STR_EQ(format_g(0.125), "0.125");
    CHECK_STR_EQ(format_general(1234567.5, 15), "1234567.5");
    CHECK_STR_EQ(format_fixed(1.5, 6), "1.500000");
    CHECK_STR_EQ(format_fixed_trimmed(370.3701, 3), "370.37");
    CHECK_STR_EQ(format_g(1e-5), "1e-05");
}
